];

function HudButton({
  active,
  onClick,
  children,
}: {
  active?: boolean;
  onClick: () => void;
  children: React.ReactNode;
}) {
  return (
    <button
      onClick={onClick}
      // Layer toggles are not the primary action — the accent belongs to
      // "Run study". Three saturated chips in the corner were the loudest
