              }`}
            />
            {total === 0 ? (
              <span className="text-fg-muted">
                {planning || running ? "Planning placements" : "No simulations"}
              </span>
            ) : (
              <>
                <span className="font-mono text-fg-muted">
                  <span className="text-fg">{done}</span>/{total} solved
                </span>
                <span
