                  if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) run();
                }}
                spellCheck={false}
                placeholder="2.4 GHz Wi-Fi antenna on the bottom edge. 6 mm clear of the battery, VSWR under 2 in band, efficiency above 55%."
                className="block min-h-[8.5rem] w-full resize-y bg-transparent px-3.5 py-3 text-[13px] leading-6 text-fg outline-none placeholder:text-fg-faint"
              />
              <div className="flex items-center gap-2 px-2 pb-2">
                <AgentMenu value={agent} onChange={setAgent} disabled={running} />
                {started && (
                  <button
                    type="button"
                    onClick={() => setEditingSpec(false)}
                    className="text-[11px] text-fg-muted transition hover:text-fg"
                  >
                    Cancel
                  </button>
                )}
                <button
                  type="button"
                  onClick={run}
                  disabled={!canRun}
                  title="Run the placement study (Cmd + Enter)"
                  className="ml-auto flex items-center gap-2 rounded-md bg-accent px-3.5 py-1.5 text-[12.5px] font-semibold text-ink-950 transition hover:brightness-110 active:brightness-95 disabled:cursor-not-allowed disabled:bg-ink-800 disabled:text-fg-muted"
                >
                  {running ? (
                    <>
                      <Spinner />
                      Running
                    </>
                  ) : (
                    "Run study"
                  )}
                </button>
              </div>
            </div>
            {!running && blocker && (
              <p className="mt-2 text-[11px] leading-5 text-warn">{blocker}</p>
            )}
          </div>
        )}

        {started && (
          <div className="space-y-3.5 px-5 py-5">
            {transcript.map((m) => (
              <TranscriptLine key={m.id} line={read(m)} />
            ))}
            {planning && (
              <div className="think-in flex items-center gap-2 pt-1">
                <Spinner className="text-accent" />
                <span className="text-[11px] text-fg-muted">Planning placements…</span>
              </div>
            )}
            {!transcript.length && !planning && (
              <p className="text-[11px] leading-5 text-fg-muted">Waiting for the agent.</p>
            )}
          </div>
        )}
      </div>

      {running && (
        <form
          className="shrink-0 border-t border-ink-800 px-5 py-3"
          onSubmit={(e) => {
            e.preventDefault();
            const t = note.trim();
            if (!t) return;
            setNote("");
            void sendNote(t);
          }}
        >
          <div className="flex gap-2">
            <input
              id="agent-note"
              type="text"
              value={note}
              onChange={(e) => setNote(e.target.value)}
              aria-label="Note to the agent"
              title="Lands with the agent's next iteration; it does not restart the run."
              placeholder="Note to the agent…"
              className="min-w-0 flex-1 rounded-md border border-ink-700 bg-ink-900 px-3 py-2 text-[12.5px] text-fg outline-none transition placeholder:text-fg-faint focus:border-accent"
            />
            <button
              type="submit"
              disabled={!note.trim()}
              className="shrink-0 rounded-md border border-ink-700 px-3 text-[12px] text-fg transition hover:border-accent disabled:cursor-not-allowed disabled:border-ink-800 disabled:text-fg-muted"
            >
              Send
            </button>
          </div>
        </form>
      )}
    </div>
  );
}
'''
